H.background();
const r = 2.0;
const v = Math.max(P.v, 0.1);
const omega = v / r;
const ac = v * v / r;
H.text("Uniform circular motion: a = v^2 / r", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Speed is constant; velocity turns, so accel points to the center", 24, 52, { color: H.colors.sub, size: 13 });
const cx = H.W * 0.5, cy = H.H * 0.55;
const R = 150;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 4, { fill: H.colors.sub });
const ang = omega * t;
const px = cx + R * Math.cos(ang);
const py = cy - R * Math.sin(ang);
H.line(cx, cy, px, py, { color: H.colors.axis, width: 1, dash: [4, 4] });
const vx = -Math.sin(ang), vy = -Math.cos(ang);
const vLen = 70;
H.arrow(px, py, px + vx * vLen, py + vy * vLen, { color: H.colors.accent, width: 4 });
H.text("v", px + vx * vLen + 6, py + vy * vLen, { color: H.colors.accent, size: 13, baseline: "middle" });
const aLen = 30 + ac * 6;
const ax = (cx - px), ay = (cy - py);
const aMag = Math.sqrt(ax * ax + ay * ay) || 1;
H.arrow(px, py, px + ax / aMag * Math.min(aLen, R - 10), py + ay / aMag * Math.min(aLen, R - 10), { color: H.colors.warn, width: 4 });
H.text("a", px + ax / aMag * 40, py + ay / aMag * 40, { color: H.colors.warn, size: 13, baseline: "middle" });
H.circle(px, py, 9, { fill: H.colors.accent2, stroke: H.colors.ink, width: 2 });
H.text("v = " + v.toFixed(1) + " m/s   r = " + r.toFixed(1) + " m", 24, 76, { color: H.colors.accent, size: 13 });
H.text("omega = v/r = " + omega.toFixed(2) + " rad/s", 24, 96, { color: H.colors.violet, size: 13 });
H.text("a_c = v^2/r = " + ac.toFixed(2) + " m/s^2", 24, 116, { color: H.colors.warn, size: 13 });
H.legend([{ label: "velocity (tangent)", color: H.colors.accent }, { label: "accel (centripetal)", color: H.colors.warn }], H.W - 230, 80);
